```javascript
// VectorSearchFunction - index.js
const { BedrockRuntimeClient, InvokeModelCommand } = require("@aws-sdk/client-bedrock-runtime");

async function invokeBedrockWithRetry(params, maxRetries = 3) {
  let lastError;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const client = new BedrockRuntimeClient({ region: "us-east-1" });
      const response = await client.send(new InvokeModelCommand(params));
      return response;
    } catch (error) {
      if (error.name === 'ThrottlingException') {
        const waitTime = Math.pow(2, attempt) * 1000; // 1초, 2초, 4초
        console.log(`Throttled. Retrying in ${waitTime}ms... (Attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, waitTime));
        lastError = error;
      } else {
        throw error; // 다른 에러는 즉시 throw
      }
    }
  }
  throw lastError;
}
```

