// VectorSearchFunction.js
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

async function vectorSearchWithRetry(query, maxRetries = 3) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await bedrockClient.callEmbedding(query);
    } catch (error) {
      if (error.name === 'ThrottlingException' && attempt < maxRetries - 1) {
        const delay = Math.pow(2, attempt) * 1000; // 1s, 2s, 4s
        console.log(`Retry after ${delay}ms...`);
        await sleep(delay);
      } else {
