// GetPartsFunction 코드 수정
const retryConfig = {
  maxRetries: 3,
  baseDelay: 100, // ms
  maxDelay: 5000
};

async function queryWithRetry(params) {
  for (let i = 0; i < retryConfig.maxRetries; i++) {
    try {
      return await dynamodb.query(params).promise();
    } catch (error) {
      if (error.code === 'ProvisionedThroughputExceededException' && i < retryConfig.maxRetries - 1) {
        const delay = Math.min(
          retryConfig.baseDelay * Math.pow(2, i),
          retryConfig.maxDelay
        );
        await new Promise(r => setTimeout(r, delay));
      } else {
        throw error;
      }
    }
  }
}
```

